-- ═══════════════════════════════════════════════════════════
--  GMS — FULL DATABASE SETUP + DUMMY DATA (v3) — PostgreSQL / Supabase
--
--  Converted from the original MySQL/MariaDB setup for use in a
--  Supabase PostgreSQL project (FastAPI + SQLAlchemy backend).
--
--  ⚠️  DESTRUCTIVE: drops and recreates all GMS tables, the
--  updated_at trigger function, and the distance helper function
--  in the CURRENT database. Does NOT create/drop the database
--  itself — run this inside your existing Supabase project via
--  the SQL Editor.
--
--  Includes: all tables (users, categories, services, bookings,
--  booking_events, notifications, search_terms, reviews, messages)
--  + seed data so sign-in / home / bookings / history / chat all
--  show records immediately.
-- ═══════════════════════════════════════════════════════════

BEGIN;

-- ─── Clean slate ────────────────────────────────────
DROP TABLE IF EXISTS messages CASCADE;
DROP TABLE IF EXISTS reviews CASCADE;
DROP TABLE IF EXISTS search_terms CASCADE;
DROP TABLE IF EXISTS notifications CASCADE;
DROP TABLE IF EXISTS user_push_tokens CASCADE;
DROP TABLE IF EXISTS booking_events CASCADE;
DROP TABLE IF EXISTS bookings CASCADE;
DROP TABLE IF EXISTS services CASCADE;
DROP TABLE IF EXISTS service_categories CASCADE;
DROP TABLE IF EXISTS users CASCADE;
DROP FUNCTION IF EXISTS set_updated_at() CASCADE;
DROP FUNCTION IF EXISTS gms_distance_sphere(DOUBLE PRECISION, DOUBLE PRECISION, DOUBLE PRECISION, DOUBLE PRECISION) CASCADE;

-- ─── Helper: auto-maintain updated_at (replaces MySQL's
--      "ON UPDATE CURRENT_TIMESTAMP" column option) ────
CREATE FUNCTION set_updated_at() RETURNS TRIGGER AS $$
BEGIN
  NEW.updated_at = CURRENT_TIMESTAMP;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- ─── Helper: replaces MySQL's ST_Distance_Sphere(POINT(lng,lat), POINT(lng,lat))
--      geospatial function used for GMS's "nearby providers" distance search.
--      Great-circle (haversine) distance in meters between two lng/lat points,
--      using the same default earth radius (6,370,986 m) MySQL uses.
--      Call as: gms_distance_sphere(lon1, lat1, lon2, lat2)
CREATE FUNCTION gms_distance_sphere(
  lon1 DOUBLE PRECISION, lat1 DOUBLE PRECISION,
  lon2 DOUBLE PRECISION, lat2 DOUBLE PRECISION
) RETURNS DOUBLE PRECISION AS $$
DECLARE
  r        DOUBLE PRECISION := 6370986;
  rad_lat1 DOUBLE PRECISION := radians(lat1);
  rad_lat2 DOUBLE PRECISION := radians(lat2);
  dlat     DOUBLE PRECISION := radians(lat2 - lat1);
  dlon     DOUBLE PRECISION := radians(lon2 - lon1);
  a        DOUBLE PRECISION;
  c        DOUBLE PRECISION;
BEGIN
  IF lon1 IS NULL OR lat1 IS NULL OR lon2 IS NULL OR lat2 IS NULL THEN
    RETURN NULL;
  END IF;
  a := sin(dlat / 2) * sin(dlat / 2)
     + cos(rad_lat1) * cos(rad_lat2) * sin(dlon / 2) * sin(dlon / 2);
  c := 2 * atan2(sqrt(a), sqrt(1 - a));
  RETURN r * c;
END;
$$ LANGUAGE plpgsql IMMUTABLE;

-- ─── 1. USERS ───────────────────────────────────────
CREATE TABLE users (
  id           SERIAL          PRIMARY KEY,
  phone        VARCHAR(15)     NOT NULL UNIQUE,
  email        VARCHAR(190)    DEFAULT NULL UNIQUE,
  name         VARCHAR(100)    NOT NULL DEFAULT '',
  password_hash VARCHAR(255)   DEFAULT NULL,
  avatar_url   VARCHAR(500)    DEFAULT NULL,
  bio          TEXT            DEFAULT NULL,
  role         VARCHAR(10)     NOT NULL DEFAULT 'customer'
                 CHECK (role IN ('customer','provider')),
  -- You-page profile model ↓
  dial_code            VARCHAR(6)    NOT NULL DEFAULT '+91',
  location_text        VARCHAR(200)  NOT NULL DEFAULT '',   -- live-location display text
  address_line1        VARCHAR(200)  NOT NULL DEFAULT '',
  area_street_village  VARCHAR(200)  NOT NULL DEFAULT '',
  landmark             VARCHAR(200)  NOT NULL DEFAULT '',
  city                 VARCHAR(100)  NOT NULL DEFAULT '',
  district             VARCHAR(100)  NOT NULL DEFAULT '',
  state                VARCHAR(100)  NOT NULL DEFAULT '',
  pincode              VARCHAR(12)   NOT NULL DEFAULT '',
  country              VARCHAR(100)  NOT NULL DEFAULT 'India',
  latitude             DECIMAL(10,7) DEFAULT NULL,          -- provider/customer place
  longitude            DECIMAL(10,7) DEFAULT NULL,
  fcm_token    TEXT            DEFAULT NULL,
  last_seen_at TIMESTAMP       DEFAULT NULL,
  is_active    BOOLEAN         NOT NULL DEFAULT TRUE,
  created_at   TIMESTAMP       NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at   TIMESTAMP       NOT NULL DEFAULT CURRENT_TIMESTAMP,
  -- Safeguard against garbage values (typos, bare local file paths,
  -- a missing WHERE clause on a manual UPDATE). Allows either a full
  -- external URL (http/https — e.g. a Cloudinary or pravatar.cc link)
  -- OR a relative server path starting with /static/ (our own
  -- uploads — stored relative so they stay valid no matter what
  -- host/port the backend runs on later, see fix_avatar_url_portability.sql).
  CONSTRAINT chk_avatar_url_format
    CHECK (avatar_url IS NULL
           OR avatar_url LIKE 'http%'
           OR avatar_url LIKE '/static/%')
);
CREATE INDEX idx_users_phone ON users (phone);
CREATE INDEX idx_users_role  ON users (role);
CREATE TRIGGER trg_users_updated_at
  BEFORE UPDATE ON users
  FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- ─── 2. SERVICE CATEGORIES ──────────────────────────
CREATE TABLE service_categories (
  id         SERIAL        PRIMARY KEY,
  name       VARCHAR(80)   NOT NULL UNIQUE,
  icon_name  VARCHAR(80)   NOT NULL DEFAULT 'build',
  emoji      VARCHAR(16)   NOT NULL DEFAULT '🛠️',
  is_active  BOOLEAN       NOT NULL DEFAULT TRUE,
  sort_order INTEGER       NOT NULL DEFAULT 0,
  -- Location-based ranking (Home page "Recommended for You"): TRUE for
  -- services that can be delivered remotely (web dev, design, editing —
  -- distance shouldn't matter), FALSE (default) for on-site services
  -- (plumbing, electrical, cleaning — distance matters a lot).
  is_remote  BOOLEAN       NOT NULL DEFAULT FALSE
);

-- ─── 3. SERVICES ────────────────────────────────────
CREATE TABLE services (
  id           SERIAL          PRIMARY KEY,
  provider_id  INTEGER         NOT NULL,
  category_id  INTEGER         NOT NULL,
  title        VARCHAR(150)    NOT NULL,
  description  TEXT            DEFAULT NULL,
  price        DECIMAL(10,2)   NOT NULL DEFAULT 0.00,
  price_unit   VARCHAR(10)     NOT NULL DEFAULT 'fixed'
                 CHECK (price_unit IN ('fixed','per_hour','per_day')),
  is_primary   BOOLEAN         NOT NULL DEFAULT FALSE,   -- You-page: primary vs other services
  city         VARCHAR(100)    NOT NULL DEFAULT '',
  is_active    BOOLEAN         NOT NULL DEFAULT TRUE,
  created_at   TIMESTAMP       NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at   TIMESTAMP       NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT fk_service_provider FOREIGN KEY (provider_id) REFERENCES users(id) ON DELETE CASCADE,
  CONSTRAINT fk_service_category FOREIGN KEY (category_id) REFERENCES service_categories(id) ON DELETE RESTRICT
);
CREATE INDEX idx_services_provider ON services (provider_id);
CREATE INDEX idx_services_category ON services (category_id);
CREATE INDEX idx_services_city     ON services (city);
CREATE TRIGGER trg_services_updated_at
  BEFORE UPDATE ON services
  FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- ─── 4. BOOKINGS ────────────────────────────────────
CREATE TABLE bookings (
  id              SERIAL         PRIMARY KEY,
  customer_id     INTEGER        NOT NULL,
  provider_id     INTEGER        NOT NULL,
  service_id      INTEGER        NOT NULL,
  -- Two-step verification workflow:
  --   pending → (provider accepts + sets advance) awaiting_advance
  --           → (customer pays) confirmed → in_progress (Visiting) → completed
  --   Reschedule negotiation: reschedule_by_provider ⇄ reschedule_by_customer
  --   (unlimited iterations) until agreement, cancellation or rejection.
  --   Terminal: rejected, cancelled_by_customer, cancelled_by_provider, expired.
  status          VARCHAR(30)    NOT NULL DEFAULT 'pending'
                    CHECK (status IN ('pending','awaiting_advance','confirmed','in_progress',
                       'completed','reschedule_by_provider','reschedule_by_customer',
                       'rejected','cancelled_by_customer','cancelled_by_provider',
                       'expired')),
  scheduled_at    TIMESTAMP      DEFAULT NULL,   -- agreed time
  proposed_time   TIMESTAMP      DEFAULT NULL,   -- current reschedule proposal
  advance_amount  DECIMAL(10,2)  DEFAULT NULL,   -- provider-requested advance
  advance_paid    BOOLEAN        NOT NULL DEFAULT FALSE,
  payment_deadline TIMESTAMP     DEFAULT NULL,   -- optional; passing it → expired
  address         TEXT           DEFAULT NULL,
  customer_lat    DECIMAL(10,7)  DEFAULT NULL,   -- pinned/current location at booking time
  customer_lng    DECIMAL(10,7)  DEFAULT NULL,
  notes           TEXT           DEFAULT NULL,
  cancel_reason   TEXT           DEFAULT NULL,   -- rejection/cancellation reason
  created_at      TIMESTAMP      NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at      TIMESTAMP      NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT fk_booking_customer FOREIGN KEY (customer_id) REFERENCES users(id)    ON DELETE CASCADE,
  CONSTRAINT fk_booking_provider FOREIGN KEY (provider_id) REFERENCES users(id)    ON DELETE CASCADE,
  CONSTRAINT fk_booking_service  FOREIGN KEY (service_id)  REFERENCES services(id) ON DELETE RESTRICT
);
CREATE INDEX idx_bookings_customer ON bookings (customer_id);
CREATE INDEX idx_bookings_provider ON bookings (provider_id);
CREATE INDEX idx_bookings_status   ON bookings (status);
CREATE TRIGGER trg_bookings_updated_at
  BEFORE UPDATE ON bookings
  FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- ─── 4b. BOOKING EVENTS (timeline + reschedule history) ─
CREATE TABLE booking_events (
  id            SERIAL         PRIMARY KEY,
  booking_id    INTEGER        NOT NULL,
  actor_id      INTEGER        NOT NULL,
  actor_role    VARCHAR(10)    NOT NULL
                  CHECK (actor_role IN ('customer','provider','system')),
  action        VARCHAR(40)    NOT NULL,  -- requested | accepted | rejected |
                                          -- reschedule_proposed | proposal_accepted |
                                          -- counter_proposed | advance_requested |
                                          -- advance_paid | confirmed | started |
                                          -- completed | cancelled | expired
  reason        TEXT           DEFAULT NULL,
  proposed_time TIMESTAMP      DEFAULT NULL,
  amount        DECIMAL(10,2)  DEFAULT NULL,
  created_at    TIMESTAMP      NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT fk_event_booking FOREIGN KEY (booking_id) REFERENCES bookings(id) ON DELETE CASCADE,
  CONSTRAINT fk_event_actor   FOREIGN KEY (actor_id)   REFERENCES users(id)    ON DELETE CASCADE
);
CREATE INDEX idx_booking_events_booking ON booking_events (booking_id);

-- ─── 5. NOTIFICATIONS ───────────────────────────────
CREATE TABLE notifications (
  id         SERIAL         PRIMARY KEY,
  user_id    INTEGER        NOT NULL,
  title      VARCHAR(200)   NOT NULL,
  body       TEXT           NOT NULL,
  type       VARCHAR(50)    NOT NULL DEFAULT 'general',
  ref_id     INTEGER        DEFAULT NULL,
  data       JSONB          NOT NULL DEFAULT '{}'::jsonb,  -- deep-link metadata
  is_read    BOOLEAN        NOT NULL DEFAULT FALSE,
  created_at TIMESTAMP      NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT fk_notif_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);
CREATE INDEX idx_notifications_user         ON notifications (user_id);
CREATE INDEX idx_notifications_is_read      ON notifications (is_read);
CREATE INDEX idx_notifications_user_created ON notifications (user_id, created_at DESC);
CREATE INDEX idx_notifications_user_unread  ON notifications (user_id, is_read) WHERE is_read = FALSE;
CREATE INDEX idx_notifications_user_type    ON notifications (user_id, type);

-- ─── 5b. USER PUSH TOKENS (multi-device FCM) ─────────
CREATE TABLE user_push_tokens (
  id            SERIAL        PRIMARY KEY,
  user_id       INTEGER       NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  token         TEXT          NOT NULL UNIQUE,
  platform      VARCHAR(20)   NOT NULL DEFAULT 'android'
                  CHECK (platform IN ('android', 'ios', 'web')),
  device_id     VARCHAR(200),
  is_active     BOOLEAN       NOT NULL DEFAULT TRUE,
  created_at    TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at    TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  last_seen_at  TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX idx_push_tokens_user   ON user_push_tokens (user_id);
CREATE INDEX idx_push_tokens_active ON user_push_tokens (user_id, is_active);

-- 100-notifications-per-user retention, enforced in the database —
-- deletes only the SAME user's oldest rows beyond their newest 100.
CREATE OR REPLACE FUNCTION enforce_notification_retention()
RETURNS TRIGGER AS $$
BEGIN
  DELETE FROM notifications
  WHERE user_id = NEW.user_id
    AND id IN (
      SELECT id FROM notifications
      WHERE user_id = NEW.user_id
      ORDER BY created_at DESC, id DESC
      OFFSET 100
    );
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trg_notification_retention
  AFTER INSERT ON notifications
  FOR EACH ROW
  EXECUTE FUNCTION enforce_notification_retention();

-- ─── 6. SEARCH TERMS (suggestion engine) ────────────
CREATE TABLE search_terms (
  id           SERIAL        PRIMARY KEY,
  term         VARCHAR(120)  NOT NULL UNIQUE,
  category_id  INTEGER       DEFAULT NULL,
  source       VARCHAR(10)   NOT NULL DEFAULT 'seed'
                 CHECK (source IN ('seed','user','admin')),
  hit_count    INTEGER       NOT NULL DEFAULT 0,
  is_approved  BOOLEAN       NOT NULL DEFAULT TRUE,
  created_at   TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT fk_term_category FOREIGN KEY (category_id)
    REFERENCES service_categories(id) ON DELETE SET NULL
);
CREATE INDEX idx_search_terms_term ON search_terms (term);

-- ─── 7. REVIEWS ─────────────────────────────────────
CREATE TABLE reviews (
  id           SERIAL        PRIMARY KEY,
  booking_id   INTEGER       NOT NULL UNIQUE,
  customer_id  INTEGER       NOT NULL,
  provider_id  INTEGER       NOT NULL,
  rating       SMALLINT      NOT NULL,
  comment      TEXT          DEFAULT NULL,
  created_at   TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT fk_review_booking  FOREIGN KEY (booking_id)  REFERENCES bookings(id) ON DELETE CASCADE,
  CONSTRAINT fk_review_customer FOREIGN KEY (customer_id) REFERENCES users(id)    ON DELETE CASCADE,
  CONSTRAINT fk_review_provider FOREIGN KEY (provider_id) REFERENCES users(id)    ON DELETE CASCADE
);
CREATE INDEX idx_reviews_provider ON reviews (provider_id);

-- ─── 8. MESSAGES (chat) ─────────────────────────────
CREATE TABLE messages (
  id           BIGSERIAL       PRIMARY KEY,
  sender_id    INTEGER         NOT NULL,
  receiver_id  INTEGER         NOT NULL,
  body         TEXT            NOT NULL,
  is_read      BOOLEAN         NOT NULL DEFAULT FALSE,
  read_at      TIMESTAMP       DEFAULT NULL,
  delivered_at TIMESTAMP       DEFAULT NULL,  -- middle state: grey double tick
  created_at   TIMESTAMP       NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT fk_msg_sender   FOREIGN KEY (sender_id)   REFERENCES users(id) ON DELETE CASCADE,
  CONSTRAINT fk_msg_receiver FOREIGN KEY (receiver_id) REFERENCES users(id) ON DELETE CASCADE
);
CREATE INDEX idx_messages_pair            ON messages (sender_id, receiver_id, created_at);
CREATE INDEX idx_messages_receiver_unread ON messages (receiver_id, is_read);

