-- ─── Sanity checks (safe to run separately) ────────
SELECT 'users' t, COUNT(*) c FROM users
UNION SELECT 'categories', COUNT(*) FROM service_categories
UNION SELECT 'services', COUNT(*) FROM services
UNION SELECT 'bookings', COUNT(*) FROM bookings
UNION SELECT 'booking_events', COUNT(*) FROM booking_events
UNION SELECT 'reviews', COUNT(*) FROM reviews
UNION SELECT 'messages', COUNT(*) FROM messages
UNION SELECT 'notifications', COUNT(*) FROM notifications
UNION SELECT 'search_terms', COUNT(*) FROM search_terms;

SELECT COUNT(*) AS bookings_missing_timeline
FROM bookings b
LEFT JOIN booking_events e ON e.booking_id = b.id
WHERE e.id IS NULL;
